  ('EE', 'EE-P-13-MAJ', 'Majutuse soetamine 13%', '{"en":"Acquisition of accommodation 13%"}'::jsonb, 'Lähetusega seotud majutus on mahaarvatav', 'percent', 13, 'purchase', 'domestic', date '2025-01-01', null, 'KMS § 15 lg 1¹ ja § 30 lg 2 — töölähetusega seoses saadud majutusteenuse sisendkäibemaks on mahaarvatav', 'S', null, 190, 'vat', true, null, false, false, null, 'kms'),
