  ('EE', 'EE-P-24-K', 'Kauba soetamine 24%', '{"en":"Acquisition of goods 24%"}'::jsonb, 'Riigisisene soetamine, täielik mahaarvamine', 'percent', 24, 'purchase', 'domestic', date '2025-07-01', null, 'KMS § 15 lg 1 ja § 29 lg 1 — arvestatud käibemaksust arvatakse maha sisendkäibemaks', 'S', null, 130, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-P-24-P', 'Põhivara soetamine 24%', '{"en":"Acquisition of fixed assets 24%"}'::jsonb, 'Vormi KMD lahtris 5.2 eraldi näidatav sisendkäibemaks', 'percent', 24, 'purchase', 'domestic', date '2025-07-01', null, 'KMS § 15 lg 1 ja § 32 lg 4 — põhivara sisendkäibemaks, mida korrigeeritakse põhivara kasutusaja jooksul; vormil KMD lahter 5.2', 'S', null, 150, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-P-24-T', 'Teenuse soetamine 24%', '{"en":"Acquisition of services 24%"}'::jsonb, 'Riigisisene soetamine, täielik mahaarvamine', 'percent', 24, 'purchase', 'domestic', date '2025-07-01', null, 'KMS § 15 lg 1 ja § 29 lg 1', 'S', null, 140, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-P-ICG-24', 'Kauba ühendusesisene soetamine 24%', '{"en":"Intra-Community acquisition of goods 24%"}'::jsonb, 'Pöördmaksustamine, lahtrid 6.1, 4 ja 5', 'percent', 24, 'purchase', 'intracom_acquisition_goods', date '2025-07-01', null, 'KMS § 8 ja § 3 lg 4 — soetaja arvestab käibemaksu ise; § 29 lg 3 p 4 — arvestatud käibemaks on sisendkäibemaks; § 31 lg 2 — mahaarvamiseks ei ole arve nõutav', 'K', 'VATEX-EU-IC', 200, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-P-ICS-24', 'Teenuse saamine teise liikmesriigi maksukohustuslaselt 24%', '{"en":"Services received from a taxable person of another Member State 24%"}'::jsonb, 'Pöördmaksustamine, lahtrid 6, 4 ja 5', 'percent', 24, 'purchase', 'intracom_acquisition_services', date '2025-07-01', null, 'KMS § 10 lg 1 ja § 3 lg 4 p 2 — teenuse saaja arvestab käibemaksu; § 29 lg 3 p 3; § 31 lg 3 — mahaarvamiseks ei ole arve nõutav. KMS § 3 lg 7 — arvestamiskohustust ei teki, kui teise liikmesriigi müüja kohaldab väikeettevõtja erikorda ja tema number kannab lõppu „EX“.', 'K', 'VATEX-EU-IC', 210, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-P-IMP-24', 'Kauba import 24%, käibemaks deklaratsioonis', '{"en":"Import of goods 24%, VAT accounted for in the return"}'::jsonb, 'Maksuhalduri loal deklareeritakse impordi käibemaks lahtrites 4¹ ja 5.1', 'percent', 24, 'purchase', 'import', date '2025-07-01', null, 'KMS § 38 lg 2¹–2³ — maksuhalduri kirjalikul loal deklareeritakse impordilt arvestatav käibemaks käibedeklaratsioonis; § 29 lg 3 p 2 ja § 31 lg 4 ja 8. Vormil KMD ei ole impordi maksustatava väärtuse lahtrit: väärtus on tollideklaratsioonil.', null, null, 240, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-P-ND-24', 'Mahaarvamisõiguseta soetamine 24%', '{"en":"Acquisition with no right of deduction 24%"}'::jsonb, 'Külaliste vastuvõtu ning töötajate toitlustamise ja majutuse kulud: kogu käibemaks järgib rea kontot.', 'percent', 24, 'purchase', 'domestic', date '2025-07-01', null, 'KMS § 30 lg 1 — sisendkäibemaksu ei arvata maha külaliste vastuvõtuks ning töötajate toitlustamiseks või majutamiseks soetatud kaubalt ja teenuselt', 'S', null, 280, 'vat', false, null, false, false, null, 'kms'),
  ('EE', 'EE-P-PM-24', 'Erikorra alusel maksustatava kauba soetamine 24% (§ 41¹)', '{"en":"Acquisition under the special arrangements 24% (VAT Act § 41¹)"}'::jsonb, 'Kinnisasi, metallijäätmed, väärismetall ja metalltooted: lahtrid 7.1, 1, 4 ja 5', 'percent', 24, 'purchase', 'domestic_reverse_charge', date '2025-07-01', null, 'KMS § 41¹ lg 3 ja 4 — soetaja kajastab maksustatava väärtuse ja käibemaksu arve saamise maksustamisperioodil ning arvab sisendkäibemaksu maha samal perioodil', 'AE', 'VATEX-EU-AE', 230, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-P-SA-24-K', 'Sõiduauto tarbeks kaupade ja teenuste soetamine 24% — mahaarvamine 50%', '{"en":"Goods and services for a passenger car 24% — 50% deduction"}'::jsonb, 'Kütus, hooldus, remont, rent ja parkimine. Mahaarvamata käibemaks järgib rea kontot.', 'percent', 24, 'purchase', 'domestic', date '2025-07-01', null, 'KMS § 30 lg 3 — sama piirang sõiduauto tarbeks kaupade soetamisel ja teenuste saamisel. Vormil KMD lahter 5.4.', 'S', null, 260, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-P-SA-24-P', 'Sõiduauto soetamine 24% — mahaarvamine 50%', '{"en":"Acquisition of a passenger car 24% — 50% deduction"}'::jsonb, 'Osaliselt ettevõtluses kasutatav sõiduauto. Mahaarvamata käibemaks järgib rea kontot.', 'percent', 24, 'purchase', 'domestic', date '2025-07-01', null, 'KMS § 30 lg 3 — sõiduauto ettevõtluse tarbeks soetamisel arvatakse maha 50 protsenti sisendkäibemaksust; § 2 lg 12 määratleb sõiduauto; § 30 lg 4 loetleb erandid. Vormil KMD lahter 5.4.', 'S', null, 250, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-P-SA100-24', 'Sõiduauto 100% ettevõtluses 24%', '{"en":"Passenger car used wholly for business 24%"}'::jsonb, 'KMS § 30 lg 4 p 3–5 erand: mahaarvamine täies ulatuses, vormil KMD lahter 5.3', 'percent', 24, 'purchase', 'domestic', date '2025-07-01', null, 'KMS § 30 lg 4 p 3–5 — takso, sõiduõpe ja üksnes ettevõtluses kasutatav sõiduauto; § 30 lg 7 — kaheaastane kasutamise tingimus; § 30 lg 9 — maksukohustuslane peab tagama, et autot muul otstarbel ei kasutata. Vormil KMD lahter 5.3.', 'S', null, 270, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-P-VABA', 'Maksuvaba soetamine', '{"en":"Acquisition exempt from tax"}'::jsonb, 'Arve ilma käibemaksuta', 'percent', 0, 'purchase', 'exempt', date '2004-05-01', null, 'KMS § 16 — maksuvaba käive; soetaja arvel käibemaksu ei ole', 'E', 'VATEX-EU-132', 290, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-P-VS-24', 'Teenuse saamine ühendusevälise isikult 24%', '{"en":"Services received from a person outside the Union 24%"}'::jsonb, 'Pöördmaksustamine, lahtrid 7, 4 ja 5', 'percent', 24, 'purchase', 'foreign_services_received', date '2025-07-01', null, 'KMS § 3 lg 4 p 2 ja § 10 lg 1 — teenuse saamine ettevõtlusega tegelevalt välisriigi isikult, kes ei ole Eestis registreeritud; § 29 lg 3 p 3. Nõukogu direktiivi 2006/112/EÜ artiklid 44 ja 196.', null, null, 220, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-S-00-EXP', 'Kauba eksport', '{"en":"Export of goods"}'::jsonb, 'Maksustatav 0% määraga', 'percent', 0, 'sale', 'export', date '2004-05-01', null, 'KMS § 15 lg 3 p 1 — kauba eksport; § 37 lg 8 p 1 viimane lause vabastab ekspordiarve maksumäära aluse viitamise kohustusest', 'G', 'VATEX-EU-G', 100, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-S-00-ICG', 'Kauba ühendusesisene käive', '{"en":"Intra-Community supply of goods"}'::jsonb, 'Maksustatav 0% määraga', 'percent', 0, 'sale', 'intracom_goods', date '2004-05-01', null, 'KMS § 15 lg 3 p 2 ja § 7 lg 1 — kauba ühendusesisene käive; § 15 lg 3¹ seab tingimuseks soetaja kehtiva maksukohustuslasena registreerimise numbri ja ühendusesisese käibe aruandes kajastamise', 'K', 'VATEX-EU-IC', 80, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-S-00-ICS', 'Teenuse käive teise liikmesriigi maksukohustuslasele', '{"en":"Supply of services to a taxable person of another Member State"}'::jsonb, 'Pöördmaksustamine saaja poolt', 'percent', 0, 'sale', 'intracom_services', date '2010-01-01', null, 'KMS § 10 lg 4 p 9 ja § 15 lg 4 p 1 — teenus, mille käibe tekkimise koht ei ole Eesti; nõukogu direktiivi 2006/112/EÜ artiklid 44 ja 196', 'K', 'VATEX-EU-IC', 90, 'vat', true, null, false, false, null, 'kms'),
  ('EE', 'EE-S-05-AJA', 'Ajakirjandusväljaanne 5%', '{"en":"Press publication 5%"}'::jsonb, 'Ajakirjandusväljaande maksumäär 01.08.2022–31.12.2024', 'percent', 5, 'sale', 'domestic', date '2022-08-01', date '2024-12-31', 'KMS § 15 lg 2¹, redaktsioon RT I, 04.06.2022, 4, kehtetu alates 01.01.2025 — ajakirjandusväljaande maksumäär 5 protsenti; vormil KMD lahter 2¹', 'S', null, 70, 'vat', true, null, false, false, null, 'kms'),
