  ) as v (tax_code, document_kind, posting_type, factor_percent, account_code,
          declaration_box, box_factor_percent, report_code, sequence)
  join tax_templates t on t.country = 'EE' and t.code = v.tax_code
on conflict (tax_template_id, document_kind, posting_type, sequence) do update set
  factor_percent     = excluded.factor_percent,
  account_code       = excluded.account_code,
  declaration_box    = excluded.declaration_box,
  box_factor_percent = excluded.box_factor_percent,
  report_code        = excluded.report_code;

insert into tax_report_templates
  (country, code, name, periods, valid_from, valid_to, legal_reference, is_periodic_return)
values
  ('EE', 'EE-KMD', 'Käibedeklaratsioon (vorm KMD)', array['month']::declaration_period[], date '2025-07-01', null, 'Käibemaksuseadus § 27 lõige 1 — maksustamisperiood on kalendrikuu ja deklaratsioon esitatakse järgneva kuu 20. kuupäevaks; vorm on rahandusministri 10.06.2014 määruse nr 17 lisa 1 rahandusministri 14.05.2025 määruse nr 20 sõnastuses, kehtiv alates 01.07.2025. Vormil on lahtrite tähiseid, mida see fail ei saa tähemärgi haaval korrata: ülaindeksiga lahtrid 1¹, 1², 2¹, 2² ja 4¹ kannavad siin tähiseid 1a, 1b, 2a, 2b ja 4a ning punktiga alamlahtrid 3.1, 3.1.1, 3.2, 3.2.1, 5.1, 5.2, 5.3, 5.4, 6.1 ja 7.1 kannavad tähiseid 31, 311, 32, 321, 51, 52, 53, 54, 61 ja 71. Iga lahtri õiguslik viide nimetab vormil trükitud tähise.', true)
on conflict (country, code) do update set
  name               = excluded.name,
  periods            = excluded.periods,
  valid_from         = excluded.valid_from,
  valid_to           = excluded.valid_to,
  legal_reference    = excluded.legal_reference,
  is_periodic_return = excluded.is_periodic_return;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence,
   plus_boxes, minus_boxes, floor_zero, hidden, xml_element, legal_reference, source_key)
values
  ('EE', 'EE-KMD', '1', 'total', '24% määraga maksustatavad toimingud ja tehingud', '{"en":"Acts and transactions subject to tax at a rate of 24%"}'::jsonb, 10, array['1d', '61', '6s', '71', '7f']::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 1 — käibemaksuseadus § 15 lõige 1. Lahter koondab 24% määraga maksustatava käibe ning maksukohustuslase enda arvestatava käibemaksu aluse: kauba ühendusesisese soetamise, teise liikmesriigi maksukohustuslaselt ja välisriigi isikult saadud teenused ning § 41¹ erikorra alusel soetatu. Ekwo liidab need alamlahtritest, sest üks maks kirjutab ühte alusesse ühe lahtri.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '1a', 'base', '20% määraga maksustatavad toimingud ja tehingud', '{"en":"Acts and transactions subject to tax at a rate of 20%"}'::jsonb, 20, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 1¹ — käibemaksuseadus § 15 lõige 1 redaktsioonis, mis kehtis kuni 31.12.2023. Vormi juhendi järgi märgitakse siia maksustatava väärtuse muudatused, mis tulenevad kreeditarvetest ja §-st 29¹ ning puudutavad 20% määraga tehinguid.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '1b', 'base', '22% määraga maksustatavad toimingud ja tehingud', '{"en":"Acts and transactions subject to tax at a rate of 22%"}'::jsonb, 30, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 1² — käibemaksuseadus § 15 lõige 1 redaktsioonis, mis kehtis 01.01.2024–30.06.2025. Vormi juhendi järgi märgitakse siia maksustatava väärtuse muudatused, mis tulenevad kreeditarvetest ja §-st 29¹ ning puudutavad 22% määraga tehinguid.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '2', 'base', '9% määraga maksustatavad toimingud ja tehingud', '{"en":"Acts and transactions subject to tax at a rate of 9%"}'::jsonb, 40, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 2 — käibemaksuseadus § 15 lõige 2: raamat ja õppekirjandus (punkt 1), ravim, meditsiiniseade ja abivahend (punkt 2) ning ajakirjandusväljaanne (punkt 5, kehtiv alates 01.01.2025)', 'kmd-vorm'),
  ('EE', 'EE-KMD', '2a', 'base', '5% määraga maksustatavad toimingud ja tehingud', '{"en":"Acts and transactions subject to tax at a rate of 5%"}'::jsonb, 50, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 2¹ — käibemaksuseadus § 15 lõige 2¹, mis kehtis 01.08.2022–31.12.2024 ajakirjandusväljaande kohta; kassapõhise arvestuse korral kohaldatav § 46 lõike 2⁷ alusel kuni 31.12.2026', 'kmd-vorm'),
  ('EE', 'EE-KMD', '2b', 'base', '13% määraga maksustatavad toimingud ja tehingud', '{"en":"Acts and transactions subject to tax at a rate of 13%"}'::jsonb, 60, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 2² — käibemaksuseadus § 15 lõige 1¹, kehtiv alates 01.01.2025: majutus või majutus koos hommikusöögiga', 'kmd-vorm'),
  ('EE', 'EE-KMD', '3', 'total', '0% määraga maksustatavad toimingud ja tehingud', '{"en":"Acts and transactions subject to tax at a rate of 0%"}'::jsonb, 70, array['311', '3s', '32e', '321']::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 3 — käibemaksuseadus § 15 lõiked 3 ja 4. Ekwo liidab lahtri alamlahtritest; käesolev pakk kannab nullmääraga makse üksnes kauba ühendusesisese käibe, teise liikmesriigi maksukohustuslasele osutatud teenuse ja ekspordi kohta, seega peab uue nullmääraga maksu lisaja lisama selle lahtri ka siia valemisse.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '31', 'total', 'Kauba ühendusesisene käive ja teise liikmesriigi maksukohustuslasele või piiratud maksukohustuslasele osutatud teenuste käive kokku', '{"en":"Intra-Community supply of goods and services provided to a taxable person or taxable person with limited liability of another Member State, total"}'::jsonb, 80, array['311', '3s']::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 3.1 — käibemaksuseadus § 15 lõike 3 punkt 2 ja § 10 lõike 4 punkt 9. Lahtris 3 deklareeritud summas sisalduv.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '311', 'base', 'Kauba ühendusesisene käive', '{"en":"Intra-Community supply of goods"}'::jsonb, 90, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 3.1.1 — käibemaksuseadus § 7 lõige 1 ja § 15 lõike 3 punkt 2. Lahtris 3.1 deklareeritud summas sisalduv.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '32', 'total', 'Kauba eksport', '{"en":"Exportation of goods"}'::jsonb, 100, array['32e', '321']::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 3.2 — käibemaksuseadus § 15 lõike 3 punkt 1. Lahtris 3 deklareeritud summas sisalduv.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '321', 'base', 'Käibemaksutagastusega müük reisijale', '{"en":"Sale to passengers with return of value added tax"}'::jsonb, 110, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 3.2.1 — käibemaksuseadus § 5 lõiked 2 ja 4. Lahtris 3.2 deklareeritud summas sisalduv; käesolev pakk ei kanna reisijale käibemaksutagastusega müügi maksu, mistõttu lahter jääb tühjaks.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '4', 'tax', 'Käibemaks kokku', '{"en":"Total amount of value added tax"}'::jsonb, 120, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 4 — käibemaksuseadus § 29 lõige 2. Vormi juhend arvutab lahtri maksumääradega lahtritest 1, 1¹, 1², 2, 2¹ ja 2²; Ekwo liidab siia käibemaksu, mille dokumendid tegelikult raamatusse kirjutasid, sest pakk ei sisalda avaldiste keelt ja iga dokumendi maks on juba ümardatud.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '4a', 'tax', 'Impordilt tasumisele kuuluv käibemaks', '{"en":"Value added tax payable upon the import of the goods"}'::jsonb, 130, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 4¹ — käibemaksuseadus § 38 lõiked 2¹–2³: maksuhalduri kirjalikul loal deklareeritakse kauba impordilt arvestatav käibemaks käibedeklaratsioonis tollile tasumise asemel', 'kmd-vorm'),
  ('EE', 'EE-KMD', '5', 'total', 'Kokku sisendkäibemaksu summa, mis on seadusega lubatud maha arvata', '{"en":"Total amount of input VAT subject to deduction pursuant to law"}'::jsonb, 140, array['5g', '51', '52', '53', '54']::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 5 — käibemaksuseadus §§ 29, 30 ja 31. Lahter kannab juba piirangute järgset summat; Ekwo liidab selle alamlahtritest, sest lahtrid 5.1–5.4 on lahtri 5 osad.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '51', 'tax', 'Impordilt tasutud või tasumisele kuuluv käibemaks', '{"en":"VAT paid or payable on import"}'::jsonb, 150, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 5.1 — käibemaksuseadus § 29 lõike 3 punkt 2 ja § 31 lõiked 4 ja 8. Lahtri 5 summas sisalduv.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '52', 'tax', 'Põhivara soetamiselt tasutud või tasumisele kuuluv käibemaks', '{"en":"VAT paid or payable on acquisition of fixed assets"}'::jsonb, 160, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 5.2 — käibemaksuseadus § 32 lõige 4. Lahtri 5 summas sisalduv.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '53', 'tax', 'Ettevõtluses (100%) kasutatava sõiduauto soetamiselt ja selle tarbeks kaupade ja teenuste soetamiselt tasutud käibemaks', '{"en":"VAT paid or payable on acquisition of a car used wholly for business purposes and on goods and services for such a car"}'::jsonb, 170, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 5.3 — käibemaksuseadus § 30 lõike 4 punktid 3–5 ja lõige 6. Lahtri 5 summas sisalduv. Vormil on lahtri kõrval ka sõiduautode arv; Ekwo ei kanna seda, sest deklaratsiooni lahter on käesolevas mudelis rahasumma.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '54', 'tax', 'Osaliselt ettevõtluses kasutatava sõiduauto soetamiselt ja selle tarbeks kaupade ja teenuste soetamiselt tasutud käibemaks', '{"en":"VAT paid or payable on acquisition of a car used partially for business purposes and on goods and services for such a car"}'::jsonb, 180, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 5.4 — käibemaksuseadus § 30 lõige 3: maha arvatakse kuni 50 protsenti sisendkäibemaksust. Lahtri 5 summas sisalduv. Vormil on lahtri kõrval ka sõiduautode arv, mida Ekwo ei kanna.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '6', 'total', 'Kauba ühendusesisene soetamine ja teise liikmesriigi maksukohustuslaselt saadud teenused kokku', '{"en":"Intra-Community acquisitions of goods and services received from a taxable person of another Member State, total"}'::jsonb, 190, array['61', '6s']::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 6 — käibemaksuseadus § 8 ja § 10 lõige 1. Vormi juhend nimetab lahtri sõnaselgelt informatiivseks: summa sisaldub juba lahtris 1 ja ei mõjuta ühtki kokkuvõtet.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '61', 'base', 'Kauba ühendusesisene soetamine', '{"en":"Intra-Community acquisitions of goods"}'::jsonb, 200, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 6.1 — käibemaksuseadus § 8. Vormi juhendi järgi informatiivne lahter.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '7', 'total', 'Muu kauba soetamine ja teenuse saamine, mida maksustatakse käibemaksuga', '{"en":"Acquisition of other goods and services subject to value added tax"}'::jsonb, 210, array['71', '7f']::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 7 — käibemaksuseadus § 3 lõike 4 punktid 2 ja 5 ning § 41¹. Vormi juhendi järgi informatiivne lahter.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '71', 'base', 'Erikorra alusel maksustatava kinnisasja, metallijäätmete, väärismetalli ja metalltoodete soetamine', '{"en":"Acquisition of immovables, scrap metal, precious metal and metal products subject to value added tax under the special arrangements"}'::jsonb, 220, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 7.1 — käibemaksuseadus § 41¹ lõiked 1–4. Vormi juhendi järgi informatiivne lahter.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '8', 'base', 'Maksuvaba käive', '{"en":"Supply exempt from tax"}'::jsonb, 230, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 8 — käibemaksuseadus § 16', 'kmd-vorm'),
  ('EE', 'EE-KMD', '9', 'base', 'Erikorra alusel maksustatava kinnisasja, metallijäätmete, väärismetalli ja metalltoodete käive ning teises liikmesriigis paigaldatava või kokkupandava kauba maksustatav väärtus', '{"en":"Supply of immovables, scrap metal, precious metal and metal products under the special arrangements and taxable value of goods to be installed or assembled in another Member State"}'::jsonb, 240, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 9 — käibemaksuseadus § 41¹ lõiked 1 ja 2. Vormi juhendi järgi informatiivne lahter, ja juhend ütleb sõnaselgelt, et müüja § 41¹ käivet lahtrisse 1 ei märgita.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '10', 'tax', 'Täpsustused (+)', '{"en":"Adjustments (+)"}'::jsonb, 250, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 10 — käibemaksuseadus § 32 lõiked 1 ja 4, § 29 lõige 4 ja § 30 lõige 7: sisendkäibemaksu ümberarvestused. Käesolev pakk ei kanna ühtki maksu, mis sellesse lahtrisse kirjutaks; ümberarvestuse teeb raamatupidaja käsitsi.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '11', 'tax', 'Täpsustused (−)', '{"en":"Adjustments (−)"}'::jsonb, 260, '{}'::text[], '{}'::text[], false, false, null, 'Vorm KMD, lahter 11 — samad alused kui lahtril 10. Vormi juhendi järgi ei täideta lahtreid 10 ja 11 üheaegselt.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '1d', 'base', '24% määraga maksustatav käive Eestis', '{"en":"Supply taxable at 24% in Estonia"}'::jsonb, 270, '{}'::text[], '{}'::text[], false, true, null, 'Lahtri 1 osa, mida vorm eraldi ei trüki. Käibemaksuseadus § 15 lõige 1. Ekwo lisab selle, sest üks maks kirjutab dokumendiliigi kohta ühe aluse ühte lahtrisse ja lahter 1 koondab mitut allikat.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '3s', 'base', 'Teise liikmesriigi maksukohustuslasele osutatud teenuste käive', '{"en":"Services provided to a taxable person of another Member State"}'::jsonb, 280, '{}'::text[], '{}'::text[], false, true, null, 'Lahtri 3.1 osa, mida vorm eraldi ei trüki ja mille vorm annab vahena 3.1 − 3.1.1. Käibemaksuseadus § 10 lõike 4 punkt 9 ja § 15 lõike 4 punkt 1.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '32e', 'base', 'Kauba eksport, välja arvatud käibemaksutagastusega müük reisijale', '{"en":"Export of goods other than a tax-free sale to a traveller"}'::jsonb, 290, '{}'::text[], '{}'::text[], false, true, null, 'Lahtri 3.2 osa, mida vorm eraldi ei trüki ja mille vorm annab vahena 3.2 − 3.2.1. Käibemaksuseadus § 15 lõike 3 punkt 1.', 'kmd-vorm'),
  ('EE', 'EE-KMD', '5g', 'tax', 'Mahaarvatav sisendkäibemaks, mida lahtrid 5.1–5.4 ei kajasta', '{"en":"Deductible input VAT not shown in boxes 5.1 to 5.4"}'::jsonb, 300, '{}'::text[], '{}'::text[], false, true, null, 'Lahtri 5 osa, mida vorm eraldi ei trüki. Käibemaksuseadus § 29 lõiked 1 ja 3 ning § 31.', 'kmd-vorm'),
