insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('EE', 'reverse_charge', 'reverse_charge', 'Pöördmaksustamine', '{"en":"Reverse charge"}'::jsonb, 10, date '1970-01-01', null, 'Käibemaksuseadus § 37 lõige 8 punkt 2 — märge „pöördmaksustamine“ on seaduses sätestatud sõnastuses ja seda ei saa § 37 lõike 8¹ alusel muu märkega asendada'),
  ('EE', 'intracom_goods', 'intra_eu_goods', 'Kauba ühendusesisene käive, maksustatav 0% määraga — KMS § 15 lg 3 p 2; nõukogu direktiivi 2006/112/EÜ artikkel 138.', '{"en":"Intra-Community supply of goods, taxable at 0% — VAT Act § 15 (3) 2); Council Directive 2006/112/EC, Article 138."}'::jsonb, 20, date '1970-01-01', null, 'Käibemaksuseadus § 37 lõige 8 punkt 1 — nullmääraga maksustatava käibe puhul viide § 15 lõike 3 vastavale punktile või direktiivi artiklile 138'),
  ('EE', 'intracom_services', 'intra_eu_services', 'Pöördmaksustamine — käibemaksu tasub teenuse saaja. Nõukogu direktiivi 2006/112/EÜ artiklid 44 ja 196.', '{"en":"Reverse charge — value added tax is payable by the recipient of the service. Council Directive 2006/112/EC, Articles 44 and 196."}'::jsonb, 30, date '1970-01-01', null, 'Käibemaksuseadus § 37 lõige 8 punkt 2 koostoimes § 10 lõikega 1 — teenuse käibe tekkimise koht ei ole Eesti ja maksu tasub saaja'),
  ('EE', 'exempt', 'exempt', 'Maksuvaba käive — KMS § 16.', '{"en":"Supply exempt from tax — VAT Act § 16."}'::jsonb, 40, date '1970-01-01', null, 'Käibemaksuseadus § 37 lõige 8 punkt 1 — maksuvaba käibe puhul viide § 16 vastavale lõikele ja punktile'),
  ('EE', 'small_business', 'small_business', 'Käibemaksu ei lisata — väikeettevõtja ei ole maksukohustuslasena registreeritud (KMS § 19).', '{"en":"No value added tax is added — the undertaking is not registered as a taxable person (VAT Act § 19)."}'::jsonb, 50, date '1970-01-01', null, 'Käibemaksuseadus § 19 lõige 1 — registreerimiskohustus tekib, kui maksustatav käive ületab kalendriaasta algusest arvates 40 000 eurot'),
  ('EE', 'late_payment', 'late_payment', 'Tasumisega viivitamise korral on müüjal õigus nõuda viivist võlaõigusseaduse § 113 lõikes 1 sätestatud määras ning sissenõudmiskulude hüvitist 40 eurot.', '{"en":"Where payment is late, the seller may claim penalty interest at the rate laid down in § 113 (1) of the Law of Obligations Act and compensation for collection costs of 40 euros."}'::jsonb, 60, date '1970-01-01', null, 'Võlaõigusseadus § 113 lõige 1 ja § 113¹ lõige 1')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
